import {createGame,loadGame,saveGame,step,buy,returnHome,replay,SAVE_KEY,WEAPONS,ARMORS,FORGE,WORLD} from './woods-engine.mjs';
import {loadArt,drawDwarf,drawItem} from './woods-art.mjs';
const $=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d'),input={},queued={};
let state=createGame(),art,paused=false,shop=false,slot='weapon',selection=0,viewGear=null,fx=[],last=0,acc=0,saveClock=0,noticeUntil=0,sound=false,audio,saveOK=true,cam=0,W=0,H=0,dpr=1;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{const old=localStorage.getItem(SAVE_KEY);if(old)state=loadGame(old)||createGame();}catch{saveOK=false;}
function persist(){try{localStorage.setItem(SAVE_KEY,saveGame(state));saveOK=true;}catch{saveOK=false;}$('#save-status').textContent=saveOK?'Progress saved on this device.':'Storage is unavailable. Keep this tab open to retain progress.';}
function clearInput(){for(const k of Object.keys(input))input[k]=false;for(const k of Object.keys(queued))queued[k]=false;document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));}
function note(text,seconds=2.5){$('#notice').textContent=text;noticeUntil=performance.now()+seconds*1000;}
function tone(freq,duration=.06){if(!sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq/2,audio.currentTime+duration);g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(2,devicePixelRatio||1);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
addEventListener('resize',resize);resize();
function freeze(value){paused=value;clearInput();document.body.classList.toggle('modal',value);}
function openMenu(){if(shop||$('#defeat').open||$('#victory').open)return;freeze(true);persist();$('#menu').showModal();}
function closeDialog(id){$(id).close();freeze(false);last=performance.now();}
$('#pause').onclick=openMenu;$('#resume').onclick=()=>closeDialog('#menu');
$('#menu').addEventListener('cancel',()=>{freeze(false);last=performance.now();});
for(const id of ['#defeat','#victory'])$(id).addEventListener('cancel',e=>e.preventDefault());
function home(){for(const d of document.querySelectorAll('dialog'))if(d.open)d.close();returnHome(state);persist();freeze(false);note('Rested. Your coins and equipment are safe.');last=performance.now();}
$('#home').onclick=home;$('#recover').onclick=home;$('#victory-home').onclick=()=>{home();openShop();};
$('#again').onclick=()=>{replay(state);persist();closeDialog('#victory');};
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=`Sound: ${sound?'on':'off'}`;tone(660);};
const keys={a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right',j:'attack',k:'dodge',' ':'dodge',l:'special'};
addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(key==='Escape'){if(shop)closeShop();else if(!paused)openMenu();return;}if(paused)return;if(key==='e'){interact();return;}if(keys[key]){e.preventDefault();input[keys[key]]=true;if(!e.repeat&&!['left','right'].includes(keys[key]))queued[keys[key]]=true;}});
addEventListener('keyup',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(keys[key]){e.preventDefault();input[keys[key]]=false;}});
for(const b of document.querySelectorAll('[data-input]')){const k=b.dataset.input;b.addEventListener('pointerdown',e=>{if(paused)return;e.preventDefault();b.setPointerCapture(e.pointerId);input[k]=true;if(!['left','right'].includes(k))queued[k]=true;b.classList.add('pressed');});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{input[k]=false;b.classList.remove('pressed');});}
addEventListener('blur',()=>{clearInput();if(!paused)openMenu();});document.addEventListener('visibilitychange',()=>{if(document.hidden){persist();if(!paused)openMenu();}});addEventListener('pagehide',persist);
function openShop(){if(!art)return;freeze(true);shop=true;slot='weapon';selection=state.weapon;$('#shop').hidden=false;$('#close-shop').focus();renderShop();}
function closeShop(){shop=false;viewGear=null;$('#shop').hidden=true;freeze(false);persist();last=performance.now();$('#interact').focus();}
function interact(){if(paused)return;if(state.x<720)openShop();else if(state.finished){replay(state);persist();note('A new run. Your equipment stays with you.');}}
$('#interact').onclick=interact;$('#close-shop').onclick=closeShop;
function renderShop(){viewGear={weapon:state.weapon,armor:state.armor,[slot]:selection};for(const b of document.querySelectorAll('[data-slot]'))b.setAttribute('aria-pressed',String(b.dataset.slot===slot));const items=slot==='weapon'?WEAPONS:ARMORS;$('#items').replaceChildren();items.forEach((item,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',`Try ${item.name}`);b.setAttribute('aria-pressed',String(i===selection));const c=document.createElement('canvas');c.width=130;c.height=165;b.append(c);drawItem(c.getContext('2d'),art,slot,i,130,165);b.onclick=()=>{selection=i;renderShop();};$('#items').append(b);});const item=items[selection],equipped=selection<=state[slot];$('#item-name').textContent=item.name;$('#item-detail').textContent=slot==='weapon'?`${item.damage} damage · yours: ${items[state.weapon].damage}`:`Blocks ${item.armor} damage · yours: ${items[state.armor].armor}`;$('#buy').textContent=equipped?(selection===state[slot]?'Equipped':'Already surpassed'):state.gold>=item.price?`Buy · ${item.price} coins`:`Need ${item.price-state.gold} more coins`;$('#buy').disabled=equipped||state.gold<item.price;$('#shop-coins').textContent=`✦ ${state.gold} coins`;$('#fitting-label').textContent=selection===state[slot]?'Your equipped gear':'Trying on · buy to equip';}
for(const b of document.querySelectorAll('[data-slot]'))b.onclick=()=>{slot=b.dataset.slot;selection=state[slot];renderShop();};
$('#buy').onclick=()=>{if(buy(state,slot,selection)){persist();renderShop();tone(850,.16);$('#fitting-label').textContent='Equipped! Ready for the trail.';}};
$('#shop').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const list=[...$('#shop').querySelectorAll('button:not(:disabled)')];const first=list[0],end=list.at(-1);if(e.shiftKey&&document.activeElement===first){end.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===end){first.focus();e.preventDefault();}});
function text(str,x,y,size=16,color='#fff6ca'){ctx.font=`900 ${size}px Nunito,system-ui`;ctx.textAlign='center';ctx.fillStyle='#163324';ctx.lineWidth=4;ctx.strokeStyle='#163324';ctx.strokeText(str,x,y);ctx.fillStyle=color;ctx.fillText(str,x,y);}
function draw(){
 ctx.clearRect(0,0,W,H);const unit=W<600?.72:1,ground=H*.70,tileW=H*art.forest.width/art.forest.height;
 cam=Math.max(0,Math.min(WORLD-W/unit,state.x-W*(state.x<760?.55:.36)/unit));const offset=(cam*.28)%tileW;for(let x=-offset-tileW;x<W;x+=tileW)ctx.drawImage(art.forest,x,0,tileW,H);
 const shade=ctx.createLinearGradient(0,0,0,H);shade.addColorStop(0,'#142b4266');shade.addColorStop(.26,'#142b4200');shade.addColorStop(.75,'#132b1b00');shade.addColorStop(1,'#092f28cc');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);
 const at=x=>(x-cam)*unit,scale=Math.min(H/720,.9)*unit;
 if(at(FORGE)>-200&&at(FORGE)<W+200){drawDwarf(ctx,art,at(FORGE),ground,{time:state.time,weapon:1,armor:1,face:1,scale:scale*.85});text('NORI · BLACKSMITH',at(FORGE),ground-235*scale,12,'#ffe294');for(let i=0;i<3;i++){const im=art.parts[4+i];ctx.drawImage(im,at(120+i*54)-15,ground-95*scale,30*scale,76*scale);}}
 if(at(760)>0&&at(760)<W)text('WILDWOODS →',at(760),ground+30,14);
 for(const e of state.enemies){if(e.hp<=0||at(e.x)<-200||at(e.x)>W+200)continue;const x=at(e.x),sz=scale*(e.kind==='master'?245:e.kind==='wisp'?148:178);ctx.save();ctx.translate(x,ground);ctx.scale(-e.face,1);let sway=e.state==='idle'?Math.sin(state.time*5+e.id)*3:e.state==='windup'?Math.sin(state.time*35)*2:0;ctx.translate(sway,e.kind==='wisp'?-18+Math.sin(state.time*3)*9:0);if(e.state==='strike')ctx.rotate(-.16);if(e.hurt>0)ctx.globalAlpha=.55;const im=art.foes[e.kind==='master'?3:e.kind==='wisp'?2:0];ctx.drawImage(im,-sz/2,-sz,sz,sz);ctx.restore();ctx.fillStyle='#163027';ctx.fillRect(x-32,ground-sz-13,64,5);ctx.fillStyle=e.kind==='master'?'#f3a958':'#dbeb9e';ctx.fillRect(x-32,ground-sz-13,64*e.hp/e.maxHp,5);if(e.state==='windup'){ctx.strokeStyle='#ffbe71';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,ground-sz-35,12,-Math.PI/2,Math.PI*1.5-Math.max(0,e.timer)*Math.PI*2);ctx.stroke();text('!',x,ground-sz-28,22,'#ffe096');}if(e.kind==='master')text('THORNKEEPER',x,ground-sz-27,12);}
 ctx.fillStyle='#102b2733';ctx.beginPath();ctx.ellipse(at(state.x),ground+3,40*scale,9*scale,0,0,Math.PI*2);ctx.fill();
 drawDwarf(ctx,art,at(state.x),ground,{...state,moving:!paused&&(input.left||input.right),scale});
 for(const f of fx){const age=(performance.now()-f.born)/1000;if(age>f.life)continue;ctx.save();ctx.globalAlpha=1-age/f.life;const x=at(f.x),y=ground-140*scale-age*55;if(['hit','hurt','kill','evaded'].includes(f.type))text(f.type==='kill'?`+${f.amount} coins`:f.type==='evaded'?'PERFECT DODGE':`${f.type==='hurt'?'−':''}${f.amount}`,x,y,f.type==='kill'?18:24,f.type==='hurt'?'#ffa995':f.type==='kill'?'#ffe087':'#fff8ce');else if(!reduce){ctx.strokeStyle=f.type==='slam'?'#e4aaff':state.weapon===2?'#ffb54e':'#fff1b5';ctx.lineWidth=5*(1-age/f.life);ctx.beginPath();if(f.type==='slam')ctx.ellipse(x,ground-10,40+age*300,10+age*35,0,0,Math.PI*2);else ctx.arc(x+f.face*30,ground-90*scale,45+age*95,f.face===1?-1.2:1.9,f.face===1?1.2:4.4);ctx.stroke();}ctx.restore();}
 fx=fx.filter(f=>performance.now()-f.born<f.life*1000);
 if(shop){const c=$('#fitting'),r=c.getBoundingClientRect();if(c.width!==Math.round(r.width*dpr)||c.height!==Math.round(r.height*dpr)){c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);}const cc=c.getContext('2d');cc.setTransform(dpr,0,0,dpr,0,0);cc.clearRect(0,0,r.width,r.height);const s=Math.min(r.width/190,r.height/320,1.8);drawDwarf(cc,art,r.width*.46,r.height*.83,{time:performance.now()/1000,...viewGear,scale:s});}
}
function hud(){const hp=Math.ceil(state.hp);$('#health i').style.width=`${hp}%`;$('#health').setAttribute('aria-valuenow',hp);$('#hp-label').textContent=`${hp} / 100`;$('#purse').textContent=`✦ ${state.gold}`;$('#power').textContent=state.power>=60?'Slam':`${Math.floor(state.power)}/60`;$('#special').disabled=state.power<60;$('#special').classList.toggle('ready',state.power>=60);$('#dodge').style.opacity=state.dodgeCD>0?.5:1;const village=state.x<760;$('#region h1').textContent=village?'Mosswhisper Village':'The Wildwoods';const dead=state.enemies.filter(e=>e.hp<=0).length;$('#objective').textContent=village?'Nori’s forge ← · Forest trail →':state.finished?'Trail cleared · return stronger':`${dead} / 6 defeated · follow the forest trail →`;$('#interact').hidden=!(state.x<720||state.finished);$('#interact').textContent=state.x<720?'Visit Nori’s forge · E':'Run the trail again · E';if(performance.now()>noticeUntil)$('#notice').textContent='';}
function frame(now){const elapsed=Math.min(.1,(now-last)/1000||0);last=now;if(!paused){acc+=elapsed;while(acc>=1/60){step(state,{...input,...Object.fromEntries(Object.entries(queued).filter(([,v])=>v))},1/60);for(const k of Object.keys(queued))queued[k]=false;for(const e of state.events){fx.push({...e,born:now,life:['slash','slam'].includes(e.type)?.45:.9});if(e.type==='hit')tone(200);if(e.type==='kill'){tone(680,.12);persist();}if(e.type==='hurt')tone(90,.12);if(e.type==='evaded')tone(900,.1);if(e.type==='defeat'){freeze(true);$('#defeat').showModal();}if(e.type==='clear'){persist();freeze(true);$('#victory').showModal();}}acc-=1/60;if(paused){acc=0;break;}}saveClock+=elapsed;if(saveClock>2){if(state.hp>0)persist();saveClock=0;}}else acc=0;draw();hud();requestAnimationFrame(frame);}
try{art=await loadArt();$('#loading').hidden=true;persist();note('Your first axe. Your first adventure.',4);requestAnimationFrame(frame);}catch(err){$('#loading').replaceChildren();const p=document.createElement('p');p.textContent='The forest artwork could not load. Please try again.';const b=document.createElement('button');b.textContent='Reload game';b.onclick=()=>location.reload();$('#loading').append(p,b);console.error(err);}
